.greeneat-sim-container {
    padding: 20px;
    background: linear-gradient(135deg, #e8f5e9 0%, #c8e6c9 50%, #f1f8e9 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

.greeneat-sim-container .greeneat-sim-header {
    background: linear-gradient(135deg, #2e7d32 0%, #43a047 50%, #66bb6a 100%);
    color: white;
    padding: 30px;
    border-radius: 20px;
    margin-bottom: 24px;
    box-shadow: 0 8px 24px rgba(46,125,50,0.3);
    text-align: center;
}

.greeneat-sim-container .greeneat-sim-header h1 {
    margin: 0 0 8px 0;
    font-size: 2rem;
    font-weight: 800;
}

.greeneat-sim-container .greeneat-sim-header p {
    margin: 0;
    font-size: 1.1rem;
    opacity: 0.9;
}

.greeneat-sim-container .greeneat-sim-period-counter {
    text-align: center;
    font-size: 1.2rem;
    font-weight: 600;
    color: #2e7d32;
    margin-bottom: 20px;
}

.greeneat-sim-container .greeneat-sim-runway-meter {
    background: white;
    border-radius: 16px;
    padding: 20px 24px;
    margin-bottom: 24px;
    box-shadow: 0 4px 16px rgba(0,0,0,0.08);
}

.greeneat-sim-container .greeneat-sim-runway-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 12px;
}

.greeneat-sim-container .greeneat-sim-runway-title {
    font-size: 1rem;
    font-weight: 700;
    text-transform: uppercase;
    color: #555;
}

.greeneat-sim-container .greeneat-sim-runway-value {
    font-size: 1.4rem;
    font-weight: 800;
    color: #333;
}

.greeneat-sim-container .greeneat-sim-runway-bar {
    width: 100%;
    height: 24px;
    background: #e0e0e0;
    border-radius: 12px;
    overflow: hidden;
}

.greeneat-sim-container .greeneat-sim-runway-fill {
    height: 100%;
    background: linear-gradient(90deg, #43a047, #66bb6a);
    border-radius: 12px;
    transition: width 0.8s ease, background 0.5s ease;
}

.greeneat-sim-container .greeneat-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 24px;
}

.greeneat-sim-container .greeneat-sim-status-card {
    background: white;
    border-radius: 14px;
    padding: 20px 16px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.07);
    transition: transform 0.3s ease;
    text-align: center;
}

.greeneat-sim-container .greeneat-sim-status-card:hover {
    transform: translateY(-4px);
}

.greeneat-sim-container .greeneat-sim-label {
    color: #777;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 6px;
    font-weight: 600;
}

.greeneat-sim-container .greeneat-sim-value {
    font-size: 1.5rem;
    font-weight: 700;
    color: #333;
}

.greeneat-sim-container .greeneat-sim-briefing {
    background: white;
    border-left: 5px solid #43a047;
    border-radius: 12px;
    padding: 20px 24px;
    margin-bottom: 20px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.06);
}

.greeneat-sim-container .greeneat-sim-briefing h3 {
    color: #2e7d32;
    font-size: 1.1rem;
    margin-bottom: 10px;
}

.greeneat-sim-container .greeneat-sim-event {
    background: #fff3e0;
    border-left: 5px solid #ff9800;
    border-radius: 12px;
    padding: 16px 20px;
    margin-bottom: 20px;
    box-shadow: 0 2px 8px rgba(255,152,0,0.15);
}

.greeneat-sim-container .greeneat-sim-event h4 {
    color: #e65100;
    font-size: 1rem;
    margin-bottom: 8px;
}

.greeneat-sim-container .greeneat-sim-controls {
    background: white;
    border-radius: 14px;
    padding: 24px;
    margin-bottom: 20px;
    box-shadow: 0 3px 12px rgba(0,0,0,0.07);
}

.greeneat-sim-container .greeneat-sim-controls h3 {
    color: #2e7d32;
    font-size: 1.1rem;
    margin-bottom: 16px;
}

.greeneat-sim-container .greeneat-sim-controls label {
    display: block;
    font-weight: 600;
    color: #555;
    margin-top: 14px;
    margin-bottom: 6px;
    font-size: 0.9rem;
}

.greeneat-sim-container .greeneat-sim-input {
    border-radius: 10px;
    border: 2px solid #e0e0e0;
    padding: 10px 14px;
    font-size: 0.95rem;
    transition: border-color 0.3s ease;
}

.greeneat-sim-container .greeneat-sim-input:focus {
    border-color: #43a047;
    box-shadow: 0 0 0 3px rgba(67,160,71,0.15);
    outline: none;
}

.greeneat-sim-container .greeneat-sim-actions {
    text-align: center;
    margin-bottom: 28px;
}

.greeneat-sim-container .greeneat-sim-actions .btn-success {
    background: linear-gradient(135deg, #2e7d32, #43a047);
    border: none;
    border-radius: 12px;
    padding: 14px 48px;
    font-size: 1.1rem;
    font-weight: 700;
    box-shadow: 0 4px 14px rgba(46,125,50,0.3);
    margin-right: 12px;
}

.greeneat-sim-container .greeneat-sim-actions .btn-success:hover {
    background: linear-gradient(135deg, #1b5e20, #2e7d32);
    transform: translateY(-2px);
}

.greeneat-sim-container .greeneat-sim-actions .btn-outline-secondary {
    border-radius: 10px;
    padding: 8px 20px;
}

.greeneat-sim-container .greeneat-sim-history {
    margin-bottom: 28px;
}

.greeneat-sim-container .greeneat-sim-charts {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 20px;
    margin-bottom: 20px;
}

.greeneat-sim-container .greeneat-sim-chart-wrapper {
    background: white;
    border-radius: 14px;
    padding: 20px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.07);
    min-height: 280px;
}

@media (max-width: 992px) {
    .greeneat-sim-container .greeneat-sim-status-cards {
        grid-template-columns: repeat(2, 1fr);
    }
    .greeneat-sim-container .greeneat-sim-charts {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 576px) {
    .greeneat-sim-container .greeneat-sim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .greeneat-sim-container .greeneat-sim-value {
        font-size: 1.15rem;
    }
    .greeneat-sim-container .greeneat-sim-header h1 {
        font-size: 1.5rem;
    }
}
/* v1.1.0: explicit option colours (USF guide §5.4 — options ignore inherited colour) */
.greeneat-sim-container .greeneat-sim-input option {
    background-color: #ffffff;
    color: #333333;
}

