(function() {
    'use strict';

    class GreenEatAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'El Momento es Ahora';
            this.version = '1.1.0';
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 48000000,
                    monthlyRevenue: 0,
                    monthlyBurn: 0,
                    runwayWeeks: 23,
                    customers: 0,
                    cac: 0,
                    ltv: 0,
                    ltvCacRatio: 0,
                    pmfScore: 0,
                    teamHealth: 85,
                    founderEquity: 100,
                    totalRaised: 0,
                    momGrowth: 0,
                    menuCostBase: 11000,
                    channelFixedBase: 2000000,
                    priceBase: 24000,
                    mktSpendBase: 500000,
                    revenueHistory: [],
                    runwayHistory: [],
                    ltvCacHistory: [],
                    pmfHistory: [],
                    burnHistory: [],
                    lastEvent: ''
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    menuStrategy: 2,
                    channelStrategy: 1,
                    pricePoint: 24000,
                    fundingDecision: 1,
                    marketingStrategy: 1,
                    pivotDecision: 1,
                    angelDecision: 3,
                    opsInvestment: 2,
                    locationDecision: 2,
                    brandInvestment: 2,
                    strategicChoice: 1
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var period = window.mySimulation.state.currentPeriod;
            var el;

            if (period === 1) {
                el = document.getElementById('menuStrategy');
                if (el) decisions.menuStrategy = parseInt(el.value);
                el = document.getElementById('channelStrategy');
                if (el) decisions.channelStrategy = parseInt(el.value);
                el = document.getElementById('pricePoint');
                if (el) decisions.pricePoint = parseInt(el.value);
                el = document.getElementById('fundingDecision');
                if (el) decisions.fundingDecision = parseInt(el.value);
                el = document.getElementById('marketingStrategy');
                if (el) decisions.marketingStrategy = parseInt(el.value);
            } else if (period === 2) {
                el = document.getElementById('pivotDecision');
                if (el) decisions.pivotDecision = parseInt(el.value);
                el = document.getElementById('angelDecision');
                if (el) decisions.angelDecision = parseInt(el.value);
            } else if (period === 3) {
                el = document.getElementById('opsInvestment');
                if (el) decisions.opsInvestment = parseInt(el.value);
                el = document.getElementById('locationDecision');
                if (el) decisions.locationDecision = parseInt(el.value);
                el = document.getElementById('brandInvestment');
                if (el) decisions.brandInvestment = parseInt(el.value);
            } else if (period === 4) {
                el = document.getElementById('strategicChoice');
                if (el) decisions.strategicChoice = parseInt(el.value);
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var eventCode = '';

            if (period === 1) {
                var menuCostMap = {1: 8000, 2: 11000, 3: 15000};
                var menuAppealMap = {1: 0.7, 2: 1.0, 3: 1.3};
                var channelReachMap = {1: 80, 2: 200, 3: 50};
                var channelFixedMap = {1: 2000000, 2: 4500000, 3: 800000};
                var mktMultMap = {1: 1.0, 2: 1.8, 3: 1.2, 4: 1.5};
                var mktCostMap = {1: 500000, 2: 6000000, 3: 1500000, 4: 3500000};

                var menuCost = menuCostMap[d.menuStrategy] || 11000;
                var menuAppeal = menuAppealMap[d.menuStrategy] || 1.0;
                var channelReach = channelReachMap[d.channelStrategy] || 80;
                var channelFixed = channelFixedMap[d.channelStrategy] || 2000000;
                var mktMult = mktMultMap[d.marketingStrategy] || 1.0;
                var mktCost = mktCostMap[d.marketingStrategy] || 500000;
                var price = d.pricePoint || 24000;

                var priceFactor = Math.pow(24000 / price, 0.7);

                var reachShock = 1.0;
                if (Math.random() < 0.4) {
                    // Instagram algorithm change: reach drops. Paid ads hit hardest; community/influencer least.
                    if (d.marketingStrategy === 2) { reachShock = 0.6; }        // paid -40%
                    else if (d.marketingStrategy === 1) { reachShock = 0.7; }   // organic -30%
                    else { reachShock = 0.9; }                                  // community / influencer -10%
                    eventCode = 'event_instagram';
                }

                var customers = Math.round(channelReach * priceFactor * menuAppeal * mktMult * reachShock);
                var monthlyRevenue = customers * price;
                var monthlyCOGS = customers * menuCost;
                var monthlyBurn = monthlyCOGS + channelFixed + Math.round(mktCost / 4);

                if (d.fundingDecision === 2) {
                    ds.cash += 80000000;
                    ds.founderEquity = 85;
                    ds.totalRaised += 80000000;
                }

                var monthlyNet = monthlyRevenue - monthlyBurn;
                ds.cash += monthlyNet * 4;
                ds.monthlyRevenue = monthlyRevenue;
                ds.monthlyBurn = monthlyBurn;
                ds.customers = customers;
                ds.menuCostBase = menuCost;
                ds.channelFixedBase = channelFixed;
                ds.priceBase = price;
                ds.mktSpendBase = mktCost;

                var pmfBase = Math.min(40, Math.round(customers * 0.15));
                pmfBase += menuAppeal >= 1.0 ? 15 : 5;
                pmfBase += priceFactor > 0.8 && priceFactor < 1.3 ? 10 : 0;
                pmfBase += d.channelStrategy === 2 ? 10 : 5;
                ds.pmfScore = Math.min(100, pmfBase);

            } else if (period === 2) {
                var prevRevenue = ds.monthlyRevenue;
                var prevBurn = ds.monthlyBurn;
                var prevCustomers = ds.customers;

                var revenueMultiplier = 1.1;
                var burnMultiplier = 1.0;
                var customerMultiplier = 1.1;
                var pmfBonus = 0;

                if (d.pivotDecision === 1) {
                    revenueMultiplier = 1.15;
                    burnMultiplier = 1.0;
                    customerMultiplier = 1.12;
                    pmfBonus = 5;
                } else if (d.pivotDecision === 2) {
                    revenueMultiplier = 1.3;
                    burnMultiplier = 1.15;
                    customerMultiplier = 1.25;
                    pmfBonus = 10;
                    ds.menuCostBase = Math.round(ds.menuCostBase * 1.1);
                } else if (d.pivotDecision === 3) {
                    revenueMultiplier = 1.2;
                    burnMultiplier = 0.9;
                    customerMultiplier = 0.85;
                    pmfBonus = 3;
                    ds.channelFixedBase = Math.round(ds.channelFixedBase * 0.8);
                } else if (d.pivotDecision === 4) {
                    revenueMultiplier = 1.5;
                    burnMultiplier = 1.2;
                    customerMultiplier = 0.6;
                    pmfBonus = 8;
                    ds.priceBase = Math.round(ds.priceBase * 1.8);
                }

                if (d.angelDecision === 1) {
                    ds.cash += 240000000;
                    ds.founderEquity = Math.round(ds.founderEquity * 0.80);
                    ds.totalRaised += 240000000;
                    ds.teamHealth = Math.max(0, ds.teamHealth - 5);
                } else if (d.angelDecision === 2) {
                    ds.cash += 180000000;
                    ds.founderEquity = Math.round(ds.founderEquity * 0.88);
                    ds.totalRaised += 180000000;
                }

                if (Math.random() < 0.6 && ds.channelFixedBase >= 4000000) {
                    burnMultiplier = burnMultiplier * 1.15;
                    eventCode = 'event_rappi';
                }

                if (!eventCode && Math.random() < 0.3) {
                    ds.cash -= 8000000;
                    ds.teamHealth = Math.max(0, ds.teamHealth - 10);
                    eventCode = 'event_inspection';
                }

                ds.monthlyRevenue = Math.round(prevRevenue * revenueMultiplier);
                ds.monthlyBurn = Math.round(prevBurn * burnMultiplier);
                ds.customers = Math.round(prevCustomers * customerMultiplier);
                ds.pmfScore = Math.min(100, ds.pmfScore + pmfBonus);

                var monthlyNet2 = ds.monthlyRevenue - ds.monthlyBurn;
                ds.cash += monthlyNet2 * 4;

                if (prevRevenue > 0) {
                    ds.momGrowth = Math.round(((ds.monthlyRevenue - prevRevenue) / prevRevenue) * 100);
                }

            } else if (period === 3) {
                var prevRev3 = ds.monthlyRevenue;
                var prevBurn3 = ds.monthlyBurn;
                var prevCust3 = ds.customers;
                var addedCost = 0;
                var growthBoost = 1.0;

                if (d.opsInvestment === 1) {
                    addedCost += 3200000;
                    growthBoost += 0.25;
                    ds.teamHealth = Math.min(100, ds.teamHealth + 8);
                } else {
                    ds.teamHealth = Math.max(0, ds.teamHealth - 10);
                }

                if (d.locationDecision === 1) {
                    addedCost += 3000000;
                    growthBoost += 0.35;
                }

                var brandBoost = 1.0;
                if (d.brandInvestment === 1) {
                    ds.cash -= 4800000;
                    brandBoost = 1.2;
                    ds.pmfScore = Math.min(100, ds.pmfScore + 8);
                }

                if (Math.random() < 0.5) {
                    growthBoost = growthBoost * 0.85;
                    eventCode = 'event_competitor';
                }

                var totalGrowth3 = growthBoost * brandBoost;
                ds.monthlyRevenue = Math.round(prevRev3 * totalGrowth3);
                ds.monthlyBurn = prevBurn3 + addedCost;
                ds.customers = Math.round(prevCust3 * totalGrowth3);

                var monthlyNet3 = ds.monthlyRevenue - ds.monthlyBurn;
                ds.cash += monthlyNet3 * 4;

                if (prevRev3 > 0) {
                    ds.momGrowth = Math.round(((ds.monthlyRevenue - prevRev3) / prevRev3) * 100);
                }

                ds.pmfScore = Math.min(100, ds.pmfScore + Math.round(growthBoost * 5));

            } else if (period === 4) {
                eventCode = 'event_acquisition';
                ds.teamHealth = Math.max(0, ds.teamHealth - 15);

                if (d.strategicChoice === 1) {
                    if (ds.momGrowth >= 35 && ds.ltvCacRatio >= 3) {
                        ds.cash += 1200000000;
                        ds.founderEquity = Math.round(ds.founderEquity * 0.75);
                        ds.totalRaised += 1200000000;
                        ds.monthlyRevenue = Math.round(ds.monthlyRevenue * 2.5);
                        ds.monthlyBurn = Math.round(ds.monthlyBurn * 3.0);
                        ds.customers = Math.round(ds.customers * 2.2);
                        ds.pmfScore = Math.min(100, ds.pmfScore + 15);
                    } else {
                        ds.cash += 600000000;
                        ds.founderEquity = Math.round(ds.founderEquity * 0.70);
                        ds.totalRaised += 600000000;
                        ds.monthlyRevenue = Math.round(ds.monthlyRevenue * 1.5);
                        ds.monthlyBurn = Math.round(ds.monthlyBurn * 2.0);
                        ds.pmfScore = Math.max(0, ds.pmfScore - 5);
                    }
                } else if (d.strategicChoice === 2) {
                    ds.monthlyRevenue = Math.round(ds.monthlyRevenue * 1.1);
                    ds.monthlyBurn = Math.round(ds.monthlyBurn * 0.95);
                    ds.teamHealth = Math.min(100, ds.teamHealth + 10);
                    ds.pmfScore = Math.min(100, ds.pmfScore + 5);
                } else if (d.strategicChoice === 3) {
                    ds.cash += 4200000000;
                    ds.founderEquity = 0;
                    ds.teamHealth = Math.max(0, ds.teamHealth - 5);
                    ds.pmfScore = Math.min(100, ds.pmfScore + 10);
                }

                var monthlyNet4 = ds.monthlyRevenue - ds.monthlyBurn;
                ds.cash += monthlyNet4 * 4;
            }

            // --- Unit economics (consistent across all rounds; Concept 303 §3.4) ---
            // CAC = total sales & marketing spend / active customers.
            // LTV = avg order value (priceBase) × 2 orders/month × 8 months  (baseline COP 384,000).
            // Baseline lands ~7-12x, matching case Exhibit 6 (~10.1x) / band 4.2-11.8x; capped at 15x as a guard.
            var acqSpend = (ds.mktSpendBase || 0) + (ds.channelFixedBase || 0);
            var cac = ds.customers > 0 ? Math.round(acqSpend / ds.customers) : 0;
            var ltv = Math.round(ds.priceBase * 2 * 8);
            ds.cac = cac;
            ds.ltv = ltv;
            ds.ltvCacRatio = cac > 0 ? Math.min(15, Math.round((ltv / cac) * 10) / 10) : 0;

            // --- Runway (weeks). Cap at 52 so the meter's 1-year full-scale reads correctly. ---
            var netBurn = ds.monthlyBurn - ds.monthlyRevenue;
            if (netBurn > 0) {
                ds.runwayWeeks = Math.max(0, Math.round((ds.cash / netBurn) * 4.33));
                ds.runwayWeeks = Math.min(52, ds.runwayWeeks);
            } else {
                ds.runwayWeeks = 52;
            }
            if (ds.cash <= 0) { ds.runwayWeeks = 0; }   // insolvent = no runway

            ds.lastEvent = eventCode;
            ds.revenueHistory.push(ds.monthlyRevenue);
            ds.burnHistory.push(ds.monthlyBurn);
            ds.runwayHistory.push(ds.runwayWeeks);
            ds.ltvCacHistory.push(ds.ltvCacRatio);
            ds.pmfHistory.push(ds.pmfScore);

            var results = {
                period: period,
                revenue: ds.monthlyRevenue,
                burn: ds.monthlyBurn,
                cash: ds.cash,
                runway: ds.runwayWeeks,
                ltvCac: ds.ltvCacRatio,
                pmf: ds.pmfScore,
                customers: ds.customers,
                equity: ds.founderEquity,
                teamHealth: ds.teamHealth,
                event: eventCode
            };

            var self = this;
            setTimeout(function() {
                // Guide §12: pass the framework's real, already-advanced state, not a hand-built stub.
                var live = (window.mySimulation && window.mySimulation.state)
                    ? window.mySimulation.state
                    : { currentPeriod: state.currentPeriod + 1, domainState: ds };
                self._updateBriefing(live);
            }, 500);

            return results;
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod',
                function(v) { return Math.min(v, 4); });
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash',
                function(v) { return 'COP ' + Math.round(v).toLocaleString(); });
            uiManager.bind('revenueDisplay', 'domainState.monthlyRevenue',
                function(v) { return 'COP ' + Math.round(v).toLocaleString(); });
            uiManager.bind('burnDisplay', 'domainState.monthlyBurn',
                function(v) { return 'COP ' + Math.round(v).toLocaleString(); });
            uiManager.bind('customersDisplay', 'domainState.customers',
                function(v) { return Math.round(v).toLocaleString(); });
            uiManager.bind('ltvCacDisplay', 'domainState.ltvCacRatio',
                function(v) { return v.toFixed(1) + 'x'; });
            uiManager.bind('pmfDisplay', 'domainState.pmfScore',
                function(v) { return v + ' / 100'; });
            uiManager.bind('equityDisplay', 'domainState.founderEquity',
                function(v) { return v + '%'; });
            uiManager.bind('teamDisplay', 'domainState.teamHealth',
                function(v) { return v + ' / 100'; });
            uiManager.bind('runwayDisplay', 'domainState.runwayWeeks',
                function(v) { return v + ' ' + window.mySimulation.t('weeks_unit'); });
        }

        getChartConfig() {
            return {
                runwayChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: this._t('chart_runway_dataset', 'Runway (weeks)'),
                            data: [],
                            borderColor: '#e53935',
                            backgroundColor: 'rgba(229,57,53,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: this._t('chart_runway_title', 'Runway Over Rounds') }
                        },
                        scales: {
                            y: { beginAtZero: true, title: { display: true, text: this._t('chart_weeks_axis', 'Weeks') } }
                        }
                    }
                },
                financialChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: this._t('chart_revenue', 'Revenue'),
                                data: [],
                                backgroundColor: 'rgba(46,125,50,0.7)',
                                borderColor: '#2e7d32',
                                borderWidth: 2
                            },
                            {
                                label: this._t('chart_burn', 'Burn Rate'),
                                data: [],
                                backgroundColor: 'rgba(229,57,53,0.7)',
                                borderColor: '#e53935',
                                borderWidth: 2
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: this._t('chart_financial_title', 'Revenue vs Burn Rate (COP)') }
                        },
                        scales: {
                            y: { beginAtZero: true }
                        }
                    }
                }
            };
