        _updateBriefing(state) {
            var rawPeriod = state.currentPeriod || 1;
            var finished = rawPeriod > 4;
            var period = Math.min(rawPeriod, 4);
            var roundIds = ['round1Decisions', 'round2Decisions', 'round3Decisions', 'round4Decisions'];

            for (var i = 0; i < roundIds.length; i++) {
                var panel = document.getElementById(roundIds[i]);
                if (panel) {
                    // once finished, hide every decision panel (the completion modal takes over)
                    panel.style.display = (!finished && i === period - 1) ? 'block' : 'none';
                }
            }

            var briefingKeys = ['briefing_r1', 'briefing_r2', 'briefing_r3', 'briefing_r4'];
            var briefEl = document.getElementById('briefingText');
            if (briefEl && window.mySimulation) {
                briefEl.innerHTML = window.mySimulation.t(briefingKeys[period - 1]);
            }

            var ds = state.domainState;
            if (ds) {
                this._updateRunwayMeter(ds);
                this._updateEventPanel(ds.lastEvent || '');
            }
        }

        _updateRunwayMeter(ds) {
            var fill = document.getElementById('runwayFill');
            if (fill) {
                var pct = Math.min(100, Math.max(0, (ds.runwayWeeks / 52) * 100));
                fill.style.width = pct + '%';
                if (pct > 50) {
                    fill.style.background = 'linear-gradient(90deg, #43a047, #66bb6a)';
                } else if (pct > 25) {
                    fill.style.background = 'linear-gradient(90deg, #ff9800, #ffc107)';
                } else {
                    fill.style.background = 'linear-gradient(90deg, #e53935, #ef5350)';
                }
            }
        }

        _updateEventPanel(eventCode) {
            var panel = document.getElementById('eventPanel');
            var text = document.getElementById('eventText');
            if (panel && text) {
                if (eventCode && window.mySimulation) {
                    panel.style.display = 'block';
                    text.innerHTML = window.mySimulation.t(eventCode);
                } else {
                    panel.style.display = 'none';
                }
            }
        }
    }

